68	export class Telemetry {
69	  private telemetryDisabledRecorded = false;
70	  private id: string;
71	  private email: string | null;
72	
73	  constructor() {
74	    this.id = getUserId();
75	    this.email = getUserEmail();
76	    void this.identify();
77	  }
78	
79	  async identify() {
80	    if (this.disabled || getEnvBool('IS_TESTING')) {
81	      return;
82	    }
83	
84	    const client = getPostHogClient();
85	    if (client) {
86	      try {
87	        client.identify({
88	          distinctId: this.id,
89	          properties: {
90	            email: this.email,
91	            isLoggedIntoCloud: isLoggedIntoCloud(),
92	            authMethod: getAuthMethod(),
93	            isRunningInCi: isCI(),
94	          },
95	        });
96	        client.flush().catch(() => {
97	          // Silently ignore flush errors
98	        });
99	      } catch (error) {
100	        logger.debug(`PostHog identify error: ${error}`);
101	      }
102	    }
103	  }
104	
105	  get disabled() {
106	    return getEnvBool('PROMPTFOO_DISABLE_TELEMETRY');
107	  }
108	
109	  private recordTelemetryDisabled() {
110	    if (!this.telemetryDisabledRecorded) {
111	      this.sendEvent('feature_used', { feature: 'telemetry disabled' });
112	      this.telemetryDisabledRecorded = true;
113	    }
114	  }
115	
116	  record(eventName: TelemetryEventTypes, properties: EventProperties): void {
117	    if (this.disabled) {
118	      this.recordTelemetryDisabled();
119	    } else {
120	      this.sendEvent(eventName, properties);
121	    }
122	  }
123	
124	  private sendEvent(eventName: TelemetryEventTypes, properties: EventProperties): void {
125	    const propertiesWithMetadata = {
126	      ...properties,
127	      packageVersion: VERSION,
128	      isRunningInCi: isCI(),
129	    };
130	
131	    const client = getPostHogClient();
132	    if (client && !getEnvBool('IS_TESTING')) {
133	      try {
134	        client.capture({
135	          distinctId: this.id,
136	          event: eventName,
137	          properties: propertiesWithMetadata,
138	        });
139	        client.flush().catch(() => {
140	          // Silently ignore flush errors
141	        });
142	      } catch (error) {
143	        logger.debug(`PostHog capture error: ${error}`);
144	      }
145	    }
146	
147	    fetchWithProxy(R_ENDPOINT, {
148	      method: 'POST',
149	      headers: {
150	        'Content-Type': 'application/json',
151	      },
152	      body: JSON.stringify({
153	        event: eventName,
154	        environment: getEnvString('NODE_ENV', 'development'),
155	        email: this.email,
156	        meta: {
157	          user_id: this.id,
158	          ...propertiesWithMetadata,
159	        },
160	      }),
161	    }).catch(() => {
162	      // pass
163	    });
164	  }
