166	  async shutdown(): Promise<void> {
167	    // Guard against multiple shutdown calls (from beforeExit + explicit shutdown in main.ts)
168	    if (isShuttingDown) {
169	      return;
170	    }
171	
172	    const client = getPostHogClient();
173	    if (!client) {
174	      // No client to shut down - don't set the flag so future shutdowns work
175	      // if telemetry becomes enabled (e.g., in test harnesses)
176	      return;
177	    }
178	
179	    isShuttingDown = true;
180	    try {
181	      await client.shutdown();
182	    } catch (error) {
183	      logger.debug(`PostHog shutdown error: ${error}`);
184	    }
185	  }
